

select * from customer limit 20


--Q1 what is the total revenue generated by male vs Female customers?
select gender, SUM(purchase_amount) as revenue
from customer
group by gender

--Q2 which customers used a discount but still spent more than average purchase amount?
select customer_id, purchase_amount
from customer 
where discount_applied = 'Yes' and purchase_amount >= (SELECT AVG(purchase_amount)from customer)

--Q3 Which are the top 5 products with the highest average review rating?
SELECT
    item_purchased,
    AVG(review_rating) AS avg_review_rating
FROM customer
GROUP BY item_purchased
ORDER BY avg_review_rating DESC
LIMIT 5;

--Q4. Compare the average purchase amounts between Standard and Express Shipping.
SELECT
    shipping_type,
    AVG(purchase_amount) AS avg_purchase_amount
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type
ORDER BY avg_purchase_amount DESC;

--Q5 Do subscribed customers spend more? Compare average
--spend and total revenue between subscribers and non-subscribers.

SELECT
    subscription_status,
    AVG(purchase_amount) AS avg_spend,
    SUM(purchase_amount) AS total_revenue,
    COUNT(*) AS total_purchases
FROM customer
GROUP BY subscription_status
ORDER BY avg_spend DESC;


--Q6. Which 5 products 
--have the highest percentage of purchases with discounts applied?
SELECT
    item_purchased,
    ROUND(
        100.0 * SUM(
            CASE
                WHEN discount_applied = 'Yes' THEN 1
                ELSE 0
            END
        ) / COUNT(*),
        2
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

--Q7. Segment customers into New, Returning,
--and Loyal based on their total number of previous purchases,
--and show the count of each segment


-- Q7: Segment customers and show the count of each segment

SELECT
    CASE
        WHEN previous_purchases = 0 THEN 'New'
        WHEN previous_purchases BETWEEN 1 AND 10 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment,
    COUNT(DISTINCT customer_id) AS customer_count
FROM customer
GROUP BY
    CASE
        WHEN previous_purchases = 0 THEN 'New'
        WHEN previous_purchases BETWEEN 1 AND 10 THEN 'Returning'
        ELSE 'Loyal'
    END
ORDER BY customer_count DESC;

--Q8 What are the top 3 most purchased products within each category

with item_counts as (
select category,
item_purchased,
count(customer_id) as total_orders,
row_number() over (partition by category order by count (customer_id)desc)as item_rank
from customer
group by category ,  item_purchased
)
SELECT item_rank, category, item_purchased, total_orders
From item_counts
WHERE  item_rank <=3

--Q9 Are customers who are repeat buyers
--(more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
COUNT(customer_id) as repeat_buyers
from customer
where previous_purchases > 5
group by subscription_status

--Q10 what is the revenue contribution of each age group?
SELECT age_group,
SUM(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;






